package net.civeira.phylax.feature.observe.observedalertrule.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class WindowMinutesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property window minutes of observed alert rule ")
  void test_window_minutes_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> WindowMinutesVO.tryFrom(null));
    Assertions.assertEquals(1, WindowMinutesVO.from(1).getWindowMinutes());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> WindowMinutesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", WindowMinutesVO.from(1).toString());
  }
}
